function same($expected,$actual) { if($expected !== $actual) throw new RuntimeException('Expected '.var_export($expected,true).' got '.var_export($actual,true)); }
function check($value) { if(!$value) throw new RuntimeException('Assertion failed'); }
function test($name,$run) { global $passed,$failed; try { $run(); $passed++; echo 'PASS '.$name.PHP_EOL; } catch(Throwable $error) { $failed++; echo 'FAIL '.$name.': '.$error->getMessage().PHP_EOL; } }
function directory($name) { global $scratch; $path = $scratch.'/'.$name; if(!is_dir($path)) mkdir($path,0700,true); return $path; }
function process($arguments) { $pipes = []; $p = proc_open($arguments, [0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']], $pipes); fclose($pipes[0]); $out = stream_get_contents($pipes[1]); $err = stream_get_contents($pipes[2]); fclose($pipes[1]); fclose($pipes[2]); return [proc_close($p), $out, $err]; }
function guard($data) { list($status,$out,$err) = process([PHP_BINARY,__FILE__,'--guard',json_encode($data)]); same(0,$status); same('',$err); return $out; }
